  addBook(input: AddBookInput!): Book!
  addUser(input: AddUserInput!): User!
  createOrganization(input: AddOrganizationInput!): Organization!
}

type Organization @key(fields: "id") {
  id: ID!
  name: String!
  alias: String!
  enabled: Boolean!
  description: String
  domains: [Domain!]!
}

type Query {
  _entities(representations: [_Any!]!): [_Entity]!
  _service: _Service!
  users(token: String!): [User!]!
  user(id: ID!): User!
  books: [Book!]!
  book: Book!
  organizations: [Organization!]!
  organization(id: String!): Organization!
}

type User @key(fields: "id") {
  id: ID!
  username: String!
  email: String!
}

scalar _Any

union _Entity = Organization | User

type _Service {
  sdl: String!
}

